program='''def transform(grid):
    """Color a tiling of 2x2 squares and three-cell L pieces."""
    from collections import defaultdict

    h, w = len(grid), len(grid[0])
    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    # The missing corner of each L determines its color.
    templates = [
        (None, 1),       # full 2x2 square
        ((0, 0), 2),     # missing top-left
        ((1, 0), 3),     # missing bottom-left
        ((0, 1), 4),     # missing top-right
        ((1, 1), 5),     # missing bottom-right (not seen in the demos)
    ]
    candidates = []
    for r in range(h - 1):
        for c in range(w - 1):
            square = {(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)}
            for missing, color in templates:
                cells = square if missing is None else square - {(r + missing[0], c + missing[1])}
                candidates.append((cells, color))

    by_cell = defaultdict(list)
    for tile in candidates:
        for cell in tile[0]:
            by_cell[cell].append(tile)

    def search(remaining, chosen):
        if not remaining:
            return chosen
        # Choose the most constrained uncovered cell first.
        cell = min(remaining, key=lambda p: sum(tile[0] <= remaining for tile in by_cell[p]))
        for tile in by_cell[cell]:
            cells, _ = tile
            if cells <= remaining:
                result = search(remaining - cells, chosen + [tile])
                if result is not None:
                    return result
        return None

    tiling = search(occupied, [])
    if tiling is None:
        raise ValueError("No tiling found")
    output = [[0 for _ in range(w)] for _ in range(h)]
    for cells, color in tiling:
        for r, c in cells:
            output[r][c] = color
    return output
'''
